# Let's create some candidate trigger patches and test them on a few clean images
# We'll try different corners, patch sizes (3, 4, 5), and patch types

def apply_patch(img, patch, corner='tl', patch_size=3):
    """Apply patch to image at specified corner (1 pixel in from edge)"""
    img = img.clone()
    h, w = img.shape[1], img.shape[2]

    if corner == 'tl':  # top-left
        y, x = 1, 1
    elif corner == 'tr':  # top-right
        y, x = 1, w - patch_size - 1
    elif corner == 'bl':  # bottom-left
        y, x = h - patch_size - 1, 1
    elif corner == 'br':  # bottom-right
        y, x = h - patch_size - 1, w - patch_size - 1
    else:
        raise ValueError("Invalid corner")

    img[:, y:y+patch_size, x:x+patch_size] = patch
    return img

